WITH RankedPosts AS (SELECT p.Id, p.Title, p.Score, p.ViewCount, p.CreationDate, p.OwnerUserId, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS UserRank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '1' YEAR), UserBadges AS (SELECT u.Id AS UserId, COUNT(DISTINCT b.Id) AS BadgeCount, SUM(CASE WHEN b.Class = 1 THEN 1 ELSE 0 END) AS GoldBadges, SUM(CASE WHEN b.Class = 2 THEN 1 ELSE 0 END) AS SilverBadges, SUM(CASE WHEN b.Class = 3 THEN 1 ELSE 0 END) AS BronzeBadges FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id), PostStatistics AS (SELECT rp.Id AS PostId, rp.Title, rp.Score, rp.ViewCount, rp.OwnerUserId, ub.BadgeCount, ub.GoldBadges, ub.SilverBadges, ub.BronzeBadges FROM RankedPosts AS rp JOIN UserBadges AS ub ON rp.OwnerUserId = ub.UserId WHERE rp.UserRank = 1), ClosedPostReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT ps.PostId, ps.Title, ps.Score, ps.ViewCount, COALESCE(cpr.CloseReasons, 'No Close Reasons') AS CloseReasons, ps.BadgeCount, ps.GoldBadges, ps.SilverBadges, ps.BronzeBadges FROM PostStatistics AS ps LEFT JOIN ClosedPostReasons AS cpr ON ps.PostId = cpr.PostId ORDER BY ps.Score DESC NULLS FIRST, ps.ViewCount DESC NULLS FIRST LIMIT 100